-- Applied 2026-07-11 via Supabase MCP migration `invoices_backfill_2025_2026`.
-- Full 2025 + 2026 QuickBooks invoice backfill for ALL QBO customers (193
-- invoices, org "Talent Edge LLC"), generated from an aggregate
-- qbo_sales_get_invoices pull (2025-01-01..2026-12-31) on 2026-07-11.
-- Upserts on (source, external_id): the 50 rows from the earlier 2026
-- eight-customer backfill are refreshed (balance/status/customer_name), the
-- remaining 143 rows are new. `status` derived as before:
-- voided (private memo) / overdue (balance due before 2026-07-11) / open / paid.
on conflict (source, external_id) do update set
  company_id = excluded.company_id,
  doc_number = excluded.doc_number,
  txn_date = excluded.txn_date,
  due_date = excluded.due_date,
  currency = excluded.currency,
  amount_cents = excluded.amount_cents,
  balance_cents = excluded.balance_cents,
  status = excluded.status,
  memo = excluded.memo,
  lines = excluded.lines,
  customer_name = excluded.customer_name,
  synced_at = now(),
  updated_at = now();
